appearances.css:
.mk{gap:4px}
.box{padding:4px 5px;gap:3px;border-radius:3px}
.row{gap:4px 1px;align-items:start}
.row>.ctl{flex:0 0 46px;min-width:0;width:46px;justify-items:center;gap:0}
.row>.ctl:has(select){flex:0 0 84px;width:84px}
.ctl label{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:0;font-size:8px;letter-spacing:-.02em;text-transform:none;line-height:1.15;text-align:center;max-width:100%}
.ctl output{font-size:8px;line-height:1.1;letter-spacing:0;white-space:nowrap}
.ctl .kn{order:-1;width:28px!important;height:28px!important;justify-self:center!important}
.ctl .kn svg{width:100%;height:100%}
.ctl select{order:-1;width:100%;font-size:9px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px}
.ctl:has(select) label{order:2}
.box>.lab{display:none}
.row:has(.ctl)>span.lab{display:none}
.lab{font-size:9px;letter-spacing:0;text-transform:none;gap:3px;align-items:center}
.row:not(:has(.ctl)){gap:2px 10px;align-items:center}
canvas{border-radius:3px}
.empty{padding:5px 8px;line-height:1.3;font-size:9px}
.asgbar{gap:4px}
.asg{gap:4px}
canvas{height:64px!important}
.mk{gap:3px}
.row:not(:has(.ctl)) label.lab{white-space:nowrap}
.row>.ctl:has(select):first-child{flex-basis:120px;width:120px}
.mk .prow{grid-template-columns:minmax(56px,1fr) auto minmax(70px,1.3fr) 32px 10px;gap:2px 5px;min-height:20px;font-size:10px}
.mk .prow select{grid-column:auto;font-size:9px;padding:1px 2px;min-height:22px;max-width:54px;border-radius:3px}
.mk .prow output{font-size:9px}
.mk .prow input[type=range]{height:14px}
.mk details.lane{padding:2px 5px;border-radius:3px}
.mk details.lane>summary{font-size:10px;padding:2px 0;letter-spacing:.04em}
.mk .tg h3{font-size:11px;margin:0 0 2px;gap:6px}
.mk .tg h3 small{font-size:9px}
.mk .asgbar input[type=search]{font-size:10px;padding:3px 6px;min-height:24px;flex:1 1 100px}
.mk .asgbar label.lab{font-size:9px;letter-spacing:0;text-transform:none;white-space:nowrap}
